resource "aws_security_group" "web_sg" {
  name        = "web-server-sg"
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"]
  }
  tags = {
    Environment = "Production"
    Compliance  = "SOC2-PCI"
    Owner       = "SecOps"
  }
}

resource "aws_instance" "web_app" {
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = "t3.medium"
  tags = {
    Environment = "Production"
    Compliance  = "SOC2-PCI"
    Owner       = "SecOps"
  }
}

